'use client';

import { zodResolver } from '@hookform/resolvers/zod';
import { useForm } from 'react-hook-form';
import { z } from 'zod';
import { Button } from '@/components/ui/button';
import {
  Form,
  FormControl,
  FormDescription,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
} from '@/components/ui/form';
import { Input } from '@/components/ui/input';
import { Textarea } from '@/components/ui/textarea';
import { Upload } from 'lucide-react';
import { useToast } from "@/hooks/use-toast";
import { cn } from '@/lib/utils';

const formSchema = z.object({
  mark1: z.string().min(5, { message: 'Please provide a descriptive mark.' }),
  mark2: z.string().min(5, { message: 'Please provide a descriptive mark.' }),
  mark3: z.string().min(5, { message: 'Please provide a descriptive mark.' }),
  proofImages: z.any().optional(),
});

type ClaimItemFormProps = {
  itemId: string;
  onSuccess: () => void;
};

export function ClaimItemForm({ itemId, onSuccess }: ClaimItemFormProps) {
  const { toast } = useToast();
  const form = useForm<z.infer<typeof formSchema>>({
    resolver: zodResolver(formSchema),
    defaultValues: {
      mark1: '',
      mark2: '',
      mark3: '',
    },
  });

  function onSubmit(values: z.infer<typeof formSchema>) {
    console.log({ itemId, ...values });
    toast({
      title: "Claim Submitted!",
      description: "The person who found the item has been notified. You will receive an update soon.",
    });
    onSuccess();
  }

  return (
    <Form {...form}>
      <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-4">
        <FormField
          control={form.control}
          name="mark1"
          render={({ field }) => (
            <FormItem>
              <FormLabel className="text-xs">Identification Mark 1</FormLabel>
              <FormControl>
                <Textarea className="text-sm min-h-[60px]" placeholder="e.g., A specific scratch on the back..." {...field} />
              </FormControl>
              <FormMessage />
            </FormItem>
          )}
        />
         <FormField
          control={form.control}
          name="mark2"
          render={({ field }) => (
            <FormItem>
              <FormLabel className="text-xs">Identification Mark 2</FormLabel>
              <FormControl>
                <Textarea className="text-sm min-h-[60px]" placeholder="e.g., Brand name, model number..." {...field} />
              </FormControl>
              <FormMessage />
            </FormItem>
          )}
        />
         <FormField
          control={form.control}
          name="mark3"
          render={({ field }) => (
            <FormItem>
              <FormLabel className="text-xs">Identification Mark 3</FormLabel>
              <FormControl>
                <Textarea className="text-sm min-h-[60px]" placeholder="e.g., A password hint, contents..." {...field} />
              </FormControl>
              <FormMessage />
            </FormItem>
          )}
        />
        <FormField
          control={form.control}
          name="proofImages"
          render={({ field }) => (
            <FormItem>
              <FormLabel className="text-xs">Proof of Ownership (Optional)</FormLabel>
              <FormControl>
                <div className="relative">
                   <Input type="file" multiple className="w-full opacity-0 z-10 h-9" />
                   <Button variant="outline" size="sm" className="absolute inset-0 w-full" type="button">
                        <Upload className="mr-2 h-4 w-4" />
                        Upload up to 3 images
                    </Button>
                </div>
              </FormControl>
              <FormDescription className="text-xs">Receipts, photos of you with the item, etc.</FormDescription>
              <FormMessage />
            </FormItem>
          )}
        />
        <Button type="submit" className="w-full" size="sm">
          Submit Claim
        </Button>
      </form>
    </Form>
  );
}
